void Select_Copy(BOOL Cut)
{
	MAPCLIENT	 MapClient;
	MAPTHING	*Thing;
	UNDO		*Undo;
	UNDO		*Child;
	DWORD		 MapID;
	BYTE		 MapBadID;
	BYTE		*CopyPtr;
	BYTE		*CopyTmpPtr;
	BYTE		*MapPtr;
	BYTE		*LinePtr;
	int		 i,j;

	if (MapCursorSel.hidden) return;
	if (!Select_CopyRequest()) return;

	Map_CorrectRect(&MapCursorSel,&MapClient);

	CopyPtr = GlobalAlloc(GPTR,MapClient.Width*MapClient.Height*MAP_CONTROLBYTES);
	if (!CopyPtr)
		{
		Misc_PrintError(hWnd,szCopyErr,NULL,MB_ICONHAND);
		return;
		}

	Select_ReleaseCopyMemory();
	MapPtr = Map.Map+MapClient.X*MAP_CONTROLBYTES+MapClient.Y*Map.Properties.Width*MAP_CONTROLBYTES;
	CopyTmpPtr = CopyPtr;
	MapBadID = Map_TranslateID(0xFE,0x01,World);

	if (Cut)
		{
		switch(WorldItemID>>24)
			{
			case 0x0E:		
			case 0x0C:		
			case 0x28:		
			case 0x1C:		
			case 0x21:		
			case 0x22:		
			case 0x25:		
				MapID = (DWORD)(Map_TranslateID((BYTE)Map.Properties.FillID,0x01,World))<<24;
				if (MapID == 0x23)
					MapID |= 0x00010100;
				else
					MapID |= 0x00020100;
				break;
			default:
				MapID = Map_TranslateWorldItem();
				break;
			}
		Map_Lock(TRUE,FALSE);
		Undo = Undo_CreateNewEntry(UNDO_CUT,szMapCut);
		Child = Undo_CreateNewChild(&Undo,TRUE,UNDO_MAPRECT,szMainMenuRectFill);
		if (!Undo_StoreMapRect(Child,&MapCursorSel,&Map))
			{
			Undo_PrintError(hWnd);
			Undo_DestroyEntry(Undo);
			Undo_Update();
			Undo = NULL;
			}
		MapChanges++;
		}

	for (j = 0; j != MapClient.Height; j++)
		{
		LinePtr = MapPtr;
		for (i = 0; i != MapClient.Width; i++, CopyTmpPtr += MAP_CONTROLBYTES, LinePtr += MAP_CONTROLBYTES)
			{
			*(CopyTmpPtr+0) = *(LinePtr+0);
			*(CopyTmpPtr+1) = *(LinePtr+1);
			*(CopyTmpPtr+2) = *(LinePtr+2);
			*(CopyTmpPtr+3) = *(LinePtr+3);
			if ((*(LinePtr+0) == MapBadID)&&(*(LinePtr+3) == 0))
				continue;

			Things_CloneAtMapPos(&MapCreatures,MapClient.X+i,MapClient.Y+j,&MapCopyThings);
			Things_CloneAtMapPos(&MapDoors,MapClient.X+i,MapClient.Y+j,&MapCopyThings);
			Things_CloneAtMapPos(&MapTraps,MapClient.X+i,MapClient.Y+j,&MapCopyThings);
			Things_CloneAtMapPos(&MapObjects,MapClient.X+i,MapClient.Y+j,&MapCopyThings);
			Things_CloneAtMapPos(&MapMagicalObjects,MapClient.X+i,MapClient.Y+j,&MapCopyThings);

			if (Cut)
				{
				Things_RemoveAtMapPosEx(&MapCreatures,MapClient.X+i,MapClient.Y+j,&Undo);
				Things_RemoveAtMapPosEx(&MapDoors,MapClient.X+i,MapClient.Y+j,&Undo);
				Things_RemoveAtMapPosEx(&MapTraps,MapClient.X+i,MapClient.Y+j,&Undo);
				Things_RemoveAtMapPosEx(&MapObjects,MapClient.X+i,MapClient.Y+j,&Undo);
				Things_RemoveAtMapPosEx(&MapMagicalObjects,MapClient.X+i,MapClient.Y+j,&Undo);
				*(LinePtr+0) = (BYTE)((MapID)>>24);
				*(LinePtr+1) = (BYTE)((MapID)>>16);
				*(LinePtr+2) = (BYTE)((MapID)>>8);
				*(LinePtr+3) = (BYTE)(MapID);
				}
			}
		MapPtr = MapPtr+Map.Properties.Width*MAP_CONTROLBYTES;
		}

	for (Thing = (MAPTHING *)MapCopyThings.next; Thing != 0; Thing = (MAPTHING *)Thing->node.next)
		{
		Thing->x = Thing->x-MapClient.X;
		Thing->y = Thing->y-MapClient.Y;
		}

	MapCopy.Width = MapClient.Width;
	MapCopy.Height = MapClient.Height;
	MapCopy.Map = CopyPtr;
	Select_UpdateCopy();

	if (Cut)
		{
		MAPRECT	MapRect;

		Map_Lock(FALSE,FALSE);
		Minimap_Redraw(hWnd);
		Info_Update();
		Files_SaveUpdate();
		Map_CorrectRect(&MapCursorSel,&MapClient);
		MapRect.x1 = MapClient.X;
		MapRect.y1 = MapClient.Y;
		MapRect.x2 = MapClient.X+MapClient.Width;
		MapRect.y2 = MapClient.Y+MapClient.Height;
		MapRect.x1--;					
		MapRect.y1--;					
		MapRect.x2++;					
		MapRect.y2++;					
		if (Map_RectangleToClient(hWnd,&MapRect,&MapClient))
			{
			MapClient.Width += MapClient.X;
			MapClient.Height += MapClient.Y;
			InvalidateRect(hWnd,(RECT *)&MapClient,FALSE);
			UpdateWindow(hWnd);
			}
		}

	return;
}

SourcePaste:
void Select_Paste(MAPCOPY *MapCopy, NODE *MapCopyThings)
{
	MAPCLIENT	 MapClient;
	MAPRECT		 MapRect;
	MAPTHING	*Thing;
	UNDO		*Undo;
	UNDO		*Child;
	BYTE		 MapBadID;
	BYTE		*CopyPtr;
	BYTE		*TmpPtr;
	BYTE		*MapPtr;
	BYTE		*LinePtr;
	int		 i,j;

	if (MapCursorSel.hidden) return;
	if (!MapCopy->Map) return;

	Map_CorrectRect(&MapCursorSel,&MapClient);
	Map_Lock(TRUE,FALSE);
	MapRect.x1 = MapClient.X;
	MapRect.y1 = MapClient.Y;
	MapRect.x2 = MapClient.X+MapCopy->Width;
	MapRect.y2 = MapClient.Y+MapCopy->Height;
	Undo = Undo_CreateNewEntry(UNDO_PASTE,szMapPaste);
	Child = Undo_CreateNewChild(&Undo,TRUE,UNDO_MAPRECT,szMainMenuRectFill);
	if (!Undo_StoreMapRect(Child,&MapRect,&Map))
		{
		Undo_PrintError(hWnd);
		Undo_DestroyEntry(Undo);
		Undo_Update();
		Undo = NULL;
		}
	MapChanges++;

	MapPtr = Map.Map+MapClient.X*MAP_CONTROLBYTES+MapClient.Y*Map.Properties.Width*MAP_CONTROLBYTES;
	CopyPtr = MapCopy->Map;
	MapBadID = Map_TranslateID(0xFE,0x01,World);

	for (j = 0; j != MapCopy->Height; j++)
		{
		if (MapClient.Y+j >= Map.Properties.Height)
			break;
		LinePtr = MapPtr;
		TmpPtr = CopyPtr;
		for (i = 0; i != MapCopy->Width; i++, LinePtr += MAP_CONTROLBYTES, TmpPtr += MAP_CONTROLBYTES)
			{
			if (MapClient.X+i >= Map.Properties.Width)
				break;
			if ((*(LinePtr+0) == MapBadID)&&(*(LinePtr+3) == 0))
				continue;

			Things_RemoveAtMapPosEx(&MapCreatures,MapClient.X+i,MapClient.Y+j,&Undo);
			Things_RemoveAtMapPosEx(&MapDoors,MapClient.X+i,MapClient.Y+j,&Undo);
			Things_RemoveAtMapPosEx(&MapTraps,MapClient.X+i,MapClient.Y+j,&Undo);
			Things_RemoveAtMapPosEx(&MapObjects,MapClient.X+i,MapClient.Y+j,&Undo);
			Things_RemoveAtMapPosEx(&MapMagicalObjects,MapClient.X+i,MapClient.Y+j,&Undo);

			if ((*(TmpPtr+0) == MapBadID)&&(*(TmpPtr+3) == 0))
				{
				*(LinePtr+0) = Map_TranslateID(0x01,0x01,World);
				*(LinePtr+1) = 0x02;
				*(LinePtr+2) = 0x01;
				*(LinePtr+3) = 0x00;
				continue;
				}

			for (Thing = (MAPTHING *)MapCopyThings->next; Thing != 0; Thing = (MAPTHING *)Thing->node.next)
				{
				if ((Thing->x == i)&&(Thing->y == j))
					{
					NODE		*List;
					MAPTHING	*NewThing;
					UINT		 Type;

					switch(Thing->node.type)
						{
						case THING_CREATURE:
							List = &MapCreatures;
							Type = UNDO_ADDCREATURE;
							break;
						case THING_DOOR:
							List = &MapDoors;
							Type = UNDO_ADDDOOR;
							break;
						case THING_TRAP:
							List = &MapTraps;
							Type = UNDO_ADDTRAP;
							break;
						case THING_OBJECT:
							List = &MapObjects;
							Type = UNDO_ADDOBJECT;
							break;
						case THING_MAGICALOBJECT:
							List = &MapMagicalObjects;
							Type = UNDO_ADDMAGIC;
							break;
						}
					NewThing = GlobalAlloc(GPTR,sizeof(MAPTHING));
					if (!NewThing) continue;
					CopyMemory(NewThing,Thing,sizeof(MAPTHING));
					NewThing->x += MapClient.X;
					NewThing->y += MapClient.Y;
					NewThing->uniqueid = 0;
					List_AddEntry((NODE *)NewThing,List);
					Child = Undo_CreateNewChild(&Undo,TRUE,0,NULL);
					Undo_StoreEntry(Child,(NODE *)NewThing,Type);
					}
				}

			*(LinePtr+0) = *(TmpPtr+0);
			*(LinePtr+1) = *(TmpPtr+1);
			*(LinePtr+2) = *(TmpPtr+2);
			*(LinePtr+3) = *(TmpPtr+3);
			}
		MapPtr += Map.Properties.Width*MAP_CONTROLBYTES;
		CopyPtr += MapCopy->Width*MAP_CONTROLBYTES;
		}

	Map_Lock(FALSE,FALSE);
	Minimap_Redraw(hWnd);
	Info_Update();
	Files_SaveUpdate();
	Map_CorrectRect(&MapCursorSel,&MapClient);
	MapRect.x1 = MapClient.X;
	MapRect.y1 = MapClient.Y;
	MapRect.x2 = MapClient.X+MapCopy->Width;
	MapRect.y2 = MapClient.Y+MapCopy->Height;
	MapRect.x1--;						
	MapRect.y1--;						
	MapRect.x2++;						
	MapRect.y2++;						
	if (Map_RectangleToClient(hWnd,&MapRect,&MapClient))
		{
		MapClient.Width += MapClient.X;
		MapClient.Height += MapClient.Y;
		InvalidateRect(hWnd,(RECT *)&MapClient,FALSE);
		UpdateWindow(hWnd);
		}

	return;
}

SourceRemoval:
void Things_RemoveAtMapPosEx(NODE *ListPtr, LONG MapX, LONG MapY, UNDO **Parent)
{
	MAPTHING	*Thing;
	UNDO		*Child;
	UINT		 Type;

	if (ListPtr == &MapCreatures) Type = UNDO_SUBCREATURE;
	else if (ListPtr == &MapDoors) Type = UNDO_SUBDOOR;
	else if (ListPtr == &MapTraps) Type = UNDO_SUBTRAP;
	else if (ListPtr == &MapObjects) Type = UNDO_SUBOBJECT;
	else if (ListPtr == &MapMagicalObjects) Type = UNDO_SUBMAGIC;

	for (Thing = (MAPTHING *)ListPtr->next; Thing != 0;)
		{
		if ((Thing->x == MapX)&&(Thing->y == MapY))
			{
			Child = Undo_CreateNewChild(Parent,TRUE,0,NULL);
			Undo_StoreEntry(Child,(NODE *)Thing,Type);
			MapChanges++;
			Thing = (MAPTHING *)ListPtr->next;
			continue;
			}
		Thing = (MAPTHING *)Thing->node.next;
		}

	return;
}

SourceUndoStore:
int Undo_StoreEntry(UNDO *Undo, NODE *Entry, UINT Type)
{
	char	*Description;
	ULONG	 Size = 0;

	switch(Type)
		{
		case UNDO_ADDCREATURE:
			Description = szMapAddCreature;
			break;
		case UNDO_SUBCREATURE:
			Description = szMapSubCreature;
			Size = sizeof(MAPTHING);
			break;
		case UNDO_MODCREATURE:
			Description = szMapModCreature;
			break;
		case UNDO_ADDDOOR:
			Description = szMapAddDoor;
			break;
		case UNDO_SUBDOOR:
			Description = szMapSubDoor;
			Size = sizeof(MAPTHING);
			break;
		case UNDO_MODDOOR:
			Description = szMapModDoor;
			break;
		case UNDO_ADDTRAP:
			Description = szMapAddTrap;
			break;
		case UNDO_SUBTRAP:
			Description = szMapSubTrap;
			Size = sizeof(MAPTHING);
			break;
		case UNDO_MODTRAP:
			Description = szMapModTrap;
			break;
		case UNDO_ADDMAGIC:
			Description = szMapAddMagicalObject;
			break;
		case UNDO_SUBMAGIC:
			Description = szMapSubMagicalObject;
			Size = sizeof(MAPTHING);
			break;
		case UNDO_MODMAGIC:
			Description = szMapModMagicalObject;
			break;
		case UNDO_ADDOBJECT:
			Description = szMapAddObject;
			break;
		case UNDO_SUBOBJECT:
			Description = szMapSubObject;
			Size = sizeof(MAPTHING);
			break;
		case UNDO_MODOBJECT:
			Description = szMapModObject;
			break;
		case UNDO_ADDBAND:
			Description = szMapAddHerosBand;
			break;
		case UNDO_SUBBAND:
			Description = szMapSubHerosBand;
			Size = sizeof(MTHBAND);
			break;
		case UNDO_MODBAND:
			Description = szMapModHerosBand;
			break;
		case UNDO_ADDAREA:
			Description = szMapAddArea;
			break;
		case UNDO_SUBAREA:
			Description = szMapSubArea;
			Size = sizeof(MAPRECTEX);
			break;
		case UNDO_MODAREA:
			Description = szMapModArea;
			break;
		case UNDO_ADDGATE:
			Description = szMapAddGate;
			break;
		case UNDO_SUBGATE:
			Description = szMapSubGate;
			Size = sizeof(MAPRECTEX);
			break;
		case UNDO_MODGATE:
			Description = szMapModGate;
			break;
		case UNDO_ADDEFFECT:
			Description = szMapAddEffect;
			break;
		case UNDO_SUBEFFECT:
			Description = szMapSubEffect;
			Size = sizeof(MAPRECTEX);
			break;
		case UNDO_MODEFFECT:
			Description = szMapModEffect;
			break;
		}



	switch(Type)
		{
		case UNDO_SUBCREATURE:
		case UNDO_SUBDOOR:
		case UNDO_SUBTRAP:
		case UNDO_SUBMAGIC:
		case UNDO_SUBOBJECT:
		case UNDO_SUBBAND:
		case UNDO_SUBAREA:
		case UNDO_SUBGATE:
		case UNDO_SUBEFFECT:
			Find_UpdateList(Entry);
			List_RemEntry(Entry);
			break;
		}



	if (Undo)
		{
		Undo->node.type = Type;
		Undo->description = Description;
		Undo->data.entry = Entry;
		InfoMemoryUsedByUndo += Size;

		switch(Type)
			{
			case UNDO_MODCREATURE:
			case UNDO_MODDOOR:
			case UNDO_MODTRAP:
			case UNDO_MODMAGIC:
			case UNDO_MODOBJECT:
				Undo->mod.thing = GlobalAlloc(GPTR,sizeof(MAPTHING));
				if (!Undo->mod.thing) return(0);
				InfoMemoryUsedByUndo += sizeof(MAPTHING);
				CopyMemory(Undo->mod.thing,Entry,sizeof(MAPTHING));
				Find_UpdateList(Entry);
				break;
			case UNDO_MODBAND:
				Undo->mod.band = GlobalAlloc(GPTR,sizeof(MTHBAND));
				if (!Undo->mod.band) return(0);
				InfoMemoryUsedByUndo += sizeof(MTHBAND);
				CopyMemory(Undo->mod.band,Entry,sizeof(MTHBAND));
				break;
			case UNDO_MODGATE:
			case UNDO_MODAREA:
			case UNDO_MODEFFECT:
				Undo->mod.entry = GlobalAlloc(GPTR,sizeof(MAPRECTEX));
				if (!Undo->mod.entry) return(0);
				InfoMemoryUsedByUndo += sizeof(MAPRECTEX);
				CopyMemory(Undo->mod.entry,Entry,sizeof(MAPRECTEX));
				Find_UpdateList(Entry);
				break;
			}
		}

	else switch(Type)
		{
		case UNDO_SUBCREATURE:
		case UNDO_SUBDOOR:
		case UNDO_SUBTRAP:
		case UNDO_SUBMAGIC:
		case UNDO_SUBOBJECT:
		case UNDO_SUBBAND:
		case UNDO_SUBAREA:
		case UNDO_SUBGATE:
		case UNDO_SUBEFFECT:
			GlobalFree(Entry);
			break;
		}

	return(1);
}
